import * as React from 'react';
import * as InfiniteMarqueePrimitive from '@exhuma/core';
import { cn } from '@/lib/utils';

export interface InfiniteMarqueeProps extends React.ComponentPropsWithoutRef<typeof InfiniteMarqueePrimitive.InfiniteMarquee> {
  className?: string;
}

export const InfiniteMarquee = React.forwardRef<HTMLDivElement, InfiniteMarqueeProps>(
  ({ className, children, ...props }, ref) => (
    <InfiniteMarqueePrimitive.InfiniteMarquee
      ref={ref}
      className={cn(
        'relative flex overflow-hidden select-none w-full py-4 [mask-image:linear-gradient(to_right,transparent,black_10%,black_90%,transparent)]',
        className
      )}
      {...props}
    >
      {children}
    </InfiniteMarqueePrimitive.InfiniteMarquee>
  )
);
InfiniteMarquee.displayName = 'InfiniteMarquee';

