solid.code:
import { Component, JSX, splitProps } from 'solid-js';
import * as InfiniteMarqueePrimitive from '@exhuma/core';

export interface InfiniteMarqueeProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const InfiniteMarquee: Component<InfiniteMarqueeProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <InfiniteMarqueePrimitive.InfiniteMarquee
      class={`relative flex overflow-hidden select-none w-full py-4 [mask-image:linear-gradient(to_right,transparent,black_10%,black_90%,transparent)] ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </InfiniteMarqueePrimitive.InfiniteMarquee>
  );
};

