import { InfiniteMarquee } from '@exhuma/core';

class ExhumaInfiniteMarqueeElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-infinite-marquee');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-infinite-marquee')) {
  customElements.define('exhuma-infinite-marquee', ExhumaInfiniteMarqueeElement);
}

react-native.code:
import React from 'react';
import { View, StyleSheet, type ViewProps } from 'react-native';
import * as InfiniteMarqueePrimitive from '@exhuma/core';

export interface InfiniteMarqueeProps extends ViewProps {
  children?: React.ReactNode;
}

export function InfiniteMarquee({ style, children, ...props }: InfiniteMarqueeProps) {
  return (
    <View style={[styles.container, style]} {...props}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: '#e2e8f0',
    backgroundColor: '#ffffff',
    padding: 20,
    overflow: 'hidden',
  },
});

